<?php
declare(strict_types=1);
date_default_timezone_set('Europe/London');
$db=new PDO('sqlite:/var/lib/predictioncomp/predictioncomp.sqlite',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function slug($v){return strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$v),'-'));}
function uk($v){return (new DateTimeImmutable($v,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Europe/London'))->format('D d M Y, H:i');}
require_once __DIR__.'/clubs.php';
$catalog=pcClubCatalog($db);
$clubMap=[];$clubNames=[];
foreach($catalog['aliases'] as $raw=>$name){$clubMap[slug($raw)]=$name;}
foreach($catalog['clubs'] as $name=>$metadata){
 $clubMap[slug($name)]=$name;
 $clubNames[$name]=[$name];
}
foreach($catalog['aliases'] as $raw=>$name)$clubNames[$name][]=$raw;
$currentClubs=array_fill_keys(pcSeasonClubs($db),true);
$teams=array_keys($currentClubs);sort($teams);

$kind=$_GET['kind']??'clubs';$club=null;$match=null;$rows=[];$page=max(1,(int)($_GET['p']??1));$pages=1;
$title='Premier League clubs';$description='Explore Premier League club fixtures, recent results and score prediction challenges on PredictionComp.';$path='/clubs';
if($kind==='club'){
 $club=$clubMap[$_GET['slug']??'']??null;
 if(!$club){http_response_code(404);$title='Club not found';$kind='missing';}
 else{$names=$clubNames[$club];$placeholders=implode(',',array_fill(0,count($names),'?'));$clubWhere="(home COLLATE NOCASE IN ($placeholders) OR away COLLATE NOCASE IN ($placeholders))";$clubParams=array_merge($names,$names);$path='/clubs/'.slug($club);$title=$club.' fixtures & predictions';$description='View '.$club.' fixtures, recent results and form. Make your own Premier League score predictions and compete with friends.';
 $q=$db->prepare("SELECT * FROM fixtures WHERE {$clubWhere} AND julianday(kickoff_utc)>=julianday('now') ORDER BY julianday(kickoff_utc)");$q->execute($clubParams);$rows=$q->fetchAll(PDO::FETCH_ASSOC);
 $q=$db->prepare("SELECT * FROM fixtures WHERE {$clubWhere} AND status IN ('FT','AET','PEN') AND home_score IS NOT NULL AND away_score IS NOT NULL ORDER BY julianday(kickoff_utc) DESC LIMIT 5");$q->execute($clubParams);$recent=$q->fetchAll(PDO::FETCH_ASSOC);}
}elseif($kind==='fixtures'){
 $path='/fixtures';$title='Premier League fixtures & results';$description='Browse the season’s Premier League fixtures and results, with UK kick-off times, club form and match prediction pages.';
 $total=(int)$db->query('SELECT COUNT(*) FROM fixtures')->fetchColumn();$pages=max(1,(int)ceil($total/20));$page=min($pages,$page);
 $rows=$db->query("SELECT * FROM fixtures ORDER BY CASE WHEN julianday(kickoff_utc)>=julianday('now') THEN 0 ELSE 1 END,CASE WHEN julianday(kickoff_utc)>=julianday('now') THEN julianday(kickoff_utc) ELSE -julianday(kickoff_utc) END LIMIT 20 OFFSET ".(($page-1)*20))->fetchAll(PDO::FETCH_ASSOC);
 if($page>1){$path.='?p='.$page;$title.=' · Page '.$page;}
}elseif($kind==='match'){
 $q=$db->prepare('SELECT * FROM fixtures WHERE id=?');$q->execute([(int)($_GET['id']??0)]);$match=$q->fetch(PDO::FETCH_ASSOC);
 if(!$match){http_response_code(404);$title='Fixture not found';$kind='missing';}
 else{$path='/fixtures/'.$match['id'];$title=$match['home'].' v '.$match['away'].' predictions & fixture';$description=$match['home'].' v '.$match['away'].' fixture details, UK kick-off time and recent team form. Enter your own prediction on PredictionComp.';}
}
require_once __DIR__.'/data-status.php';
require __DIR__.'/player-nav.php';
require __DIR__.'/seo-content.php';
if($kind==='table'){
 require __DIR__.'/standings.php';
 $seasonYear=(int)date('n')>=7?(int)date('Y'):(int)date('Y')-1;
 $standings=leagueStandings($db,$seasonYear.'-07-01T00:00:00Z',($seasonYear+1).'-07-01T00:00:00Z');
 $title='Premier League table '.$seasonYear.'/'.substr((string)($seasonYear+1),2);$path='/table';$description='Premier League standings calculated from completed results on PredictionComp, including points, goal difference and recent form.';
}


if($kind==='guides'||$kind==='guide'){
 $all=$db->query('SELECT * FROM fixtures ORDER BY julianday(kickoff_utc)')->fetchAll(PDO::FETCH_ASSOC);$weeks=[];
 foreach($all as $f)$weeks[weekKey($f['kickoff_utc'])][]=$f;
 $currentWeek=weekKey(gmdate('c'));$upcomingWeeks=array_filter($weeks,fn($key)=>$key>=$currentWeek,ARRAY_FILTER_USE_KEY);$pastWeeks=array_reverse(array_filter($weeks,fn($key)=>$key<$currentWeek,ARRAY_FILTER_USE_KEY),true);$guideWeeks=$upcomingWeeks+$pastWeeks;
 $path='/prediction-guides';$title='Weekly Premier League prediction guides';$description='Plan your Premier League score predictions with weekly fixtures, recent form, match previews and result reviews.';
 if($kind==='guide'){$key=$_GET['week']??'';if(!isset($weeks[$key])){http_response_code(404);$kind='missing';$title='Prediction guide not found';}else{$rows=$weeks[$key];$path.='/'.$key;$title='Premier League predictions: week of '.date('j M Y',strtotime($key));$description='Fixtures and factual form summaries for the week of '.date('j M Y',strtotime($key)).', with match results and player prediction insights after kick-off.';}}
}

function matchLink($f){return '/fixtures/'.(int)$f['id'];}
function fixtureRows($rows){foreach($rows as $f){$done=$f['home_score']!==null&&$f['away_score']!==null;echo '<a class="fixture" href="'.matchLink($f).'"><time>'.e(uk($f['kickoff_utc'])).' UK</time><strong>'.e($f['home']).' <span>'.($done?e($f['home_score'].'–'.$f['away_score']):'v').'</span> '.e($f['away']).'</strong><small>'.e(fixtureStatusLabel($f)).' · Match details →</small></a>';}}
