lex-basis:100%;margin-bottom:7px}.tableclub img{width:22px;height:22px;flex-basis:22px}}</style><link rel="stylesheet" href="/player-nav.css?v=5"><link rel="manifest" href="/manifest.webmanifest"><meta name="theme-color" content="#0a0f17"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="PredictionComp"><link rel="apple-touch-icon" href="/assets/app/icon-180.png"><script src="/pwa.js?v=1" defer></script><link rel="preload" href="/assets/fonts/barlow-500.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="/assets/fonts/barlow-condensed-700.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/theme.css?v=1"></head><body><header class="siteheader"><?php siteHeaderNavigation();?></header><main><p class="note"><a href="/">PredictionComp</a> / <?=e($title)?></p><h1><?=e($title)?></h1><?php if($kind!=='missing')echo dataFreshnessHtml($db);?>
